(()=>{'use strict';let featuredSelection=null,selected=null,category='',slot='blanket',horseFrame=null,horseReady=false,horsePaint=[],horseKey=0;const images=new Map(),$=id=>document.getElementById(id);const titles={dragon:['THE DRAGON SANCTUARY','Choose your guardian of the sky.'],all:['THE ADVENTURE STORE','Find your next favorite.'],motorcycle:['THE MOTORCYCLE GARAGE','Choose a bike and its matching race rider.'],car:['THE DREAM GARAGE','Pick your track personality.'],horse:['THE WINNER’S STABLE','Give your racer a signature look.'],jetski:['THE WAVE COLLECTION','Make a splash.'],subway:['THE COSTUME CLOSET','Run as someone awesome.']};
function horseRequest(){if(horseReady&&horsePaint.length){const E=window.ArcadeEconomy;horseFrame.contentWindow.postMessage({type:'shop-horse-preview',key:horseKey,entries:horsePaint.map(id=>({id,look:E.gear('horse',id)}))},location.origin)}}
function paint(){const E=window.ArcadeEconomy;horsePaint=[];document.querySelectorAll('[data-shop-art]').forEach(c=>{const it=E.catalog.find(x=>x.id===c.dataset.shopArt);if(it.category==='horse'){horsePaint.push(it.id);return}const cx=c.getContext('2d');let file=it.atlas;if(it.slot!=='skin')file=E.gear(it.category)?.atlas;const base={car:'dirt/cars.png',jetski:'wave/cars.png',subway:'races/runner.png'}[it.category];const src=file||base;let im=images.get(src);if(!im){im=new Image();images.set(src,im);im.onload=paint;im.src=src}if(!im.complete||!im.naturalWidth)return;cx.clearRect(0,0,c.width,c.height);const look=it.slot==='skin'?it:E.gear(it.category);const cols=look.columns||(file?(it.category==='subway'?4:look.single?1:2):(it.category==='subway'?6:2)),rows=look.rows||(file?(it.category==='subway'?4:look.single?1:2):2);const cw=im.naturalWidth/cols,ch=im.naturalHeight/rows,index=file?(look.single?0:(look.index||0)):0;const h=Math.min(c.height,c.width*ch/cw),w=h*cw/ch;cx.drawImage(im,(index%cols)*cw,it.category==='subway'&&file?index*ch:Math.floor(index/cols)*ch,cw,ch,(c.width-w)/2,(c.height-h)/2,w,h);if(it.slot==='trim'){cx.strokeStyle=it.color;cx.shadowColor=it.color;cx.shadowBlur=15;cx.lineWidth=5;if(it.id.endsWith('neon'))cx.strokeRect(14,14,c.width-28,c.height-28);else if(it.id.endsWith('stars')){cx.font='40px system-ui';cx.fillStyle='#ffe077';cx.fillText('★',c.width-60,55)}}});if(horsePaint.length){horseKey++;if(!horseFrame){horseFrame=document.createElement('iframe');horseFrame.hidden=true;horseFrame.title='Stable artwork';horseFrame.src='races/store-preview.html?v=real-bikes-31';document.body.append(horseFrame)}horseRequest()}}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==horseFrame?.contentWindow)return;if(e.data?.type==='shop-horse-ready'){horseReady=true;horseRequest()}if(e.data?.type==='shop-horse-art'&&e.data.key===horseKey){for(const v of e.data.entries||[]){if(!horsePaint.includes(v.id)||typeof v.svg!=='string')continue;document.querySelectorAll('[data-horse-art]').forEach(n=>{if(n.dataset.horseArt===v.id)n.innerHTML=v.svg})}}});
function art(it,hero=false){const content=plainArt(it,hero);if(['subway-4','jetski-4'].includes(it.id))return `<div class="legendaryStage moonStage" data-orbit="${it.category}">${content}<span class="orbitHint">360° · drag to turn</span></div>`;return it.rarity==='legendary'&&it.slot==='skin'?`<div class="legendaryOriginal ${hero?'hero':''}">${content}<span class="originalBadge">Original legendary artwork</span></div>`:content}
function plainArt(it,hero=false){return it.category==='horse'?`<div class="shopHorseArt ${hero?'hero':''}" data-shop-art="${it.id}" data-horse-art="${it.id}" role="img" aria-label="${it.name}">Preparing your racer…</div>`:`<canvas width="600" height="360" data-shop-art="${it.id}" aria-label="${it.name}"></canvas>`}
function render(cat,onCategory,changed,notify){const E=window.ArcadeEconomy,s=E.getState(),customOpen=category===cat&&!!$('items').querySelector('.shopCustomization')?.open;if(category!==cat){category=cat;selected=featuredSelection;featuredSelection=null}const all=E.catalog.filter(i=>cat==='all'||(i.storeCategory||i.category)===cat),skins=all.filter(i=>i.slot==='skin'||cat==='motorcycle');if(!all.some(i=>i.id===selected))selected=cat==='motorcycle'?s.loadout['horse:ride']:s.equipped[cat];const chosen=all.find(i=>i.id===selected)||skins[0];$('storeTabs').innerHTML=Object.entries({all:'← Collections',car:'Cars',horse:'Horses & gear',motorcycle:'Motorcycles',jetski:'Jet skis',subway:'Subway skins',dragon:'Dragons'}).map(([c,t])=>`<button data-shop-tab="${c}" class="${c===cat?'on':''}" aria-pressed="${c===cat}">${t}</button>`).join('');$('storeTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>onCategory(b.dataset.shopTab));
if(cat==='all'){
  const features=[['car','car-4','Race cars','Rocket-powered dreams'],['horse','horse-4','Horses & gear','Your championship stable'],['motorcycle','horse:ride:moto-gold','Motorcycles','Built for the starting grid'],['jetski','jetski-4','Jet skis','Make waves. Go legendary.'],['subway','subway-4','Subway racers','Find your next alter ego'],['dragon','dragon-4','Dragons','Claim your golden sky guardian']];
  $('items').className='restoredShop storeOverview';
  $('items').innerHTML=`<section class="collectionIntro"><span class="eyebrow">YOUR NEXT BIG ADVENTURE</span><h2>Pick your dream collection.</h2><p>Start with a favorite. Explore every ride, racer, and upgrade inside.</p></section><div class="collectionShowcase">${features.map(([cat,id,label,note])=>{const it=E.catalog.find(i=>i.id===id),count=E.catalog.filter(i=>(i.storeCategory||i.category)===cat).length;return `<button class="collectionTile ${cat}" data-collection="${cat}" data-feature="${id}" aria-label="Explore ${label}"><span class="collectionLabel">${label}</span><span class="collectionArt">${plainArt(it,true)}</span><span class="collectionCopy"><span class="collectionLegend">LEGENDARY COLLECTION</span><strong>${it.name}</strong><span>${note}</span><b>Explore ${count} options <span aria-hidden="true">→</span></b></span></button>`}).join('')}</div>`;
  $('items').querySelectorAll('[data-collection]').forEach(b=>b.onclick=()=>{featuredSelection=b.dataset.feature;onCategory(b.dataset.collection);if(!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)$('items').animate?.([{opacity:.25,transform:'translateY(12px) scale(.98)'},{opacity:1,transform:'none'}],{duration:300,easing:'cubic-bezier(.2,.8,.2,1)'});$('items').scrollIntoView?.({behavior:'smooth',block:'start'})});
  paint();window.ArcadeOrbit?.refresh();return;
}
function lockText(u){return u?.win?'Win the game to unlock':u?.factsNeeded?'Confirm '+u.factsNeeded.toLocaleString()+' more fact'+(u.factsNeeded===1?'':'s')+' to unlock':'Confirm facts to unlock'}
function card(i){const owned=s.owned.includes(i.id),unlocked=s.unlocked.includes(i.id),equipped=(i.slot==='skin'?s.equipped[i.category]:s.loadout[i.category+':'+i.slot])===i.id && !(i.category==='horse'&&i.slot!=='ride'&&E.gear('horse').ride==='moto'),hot=s.pendingUnlocks.includes(i.id),need=i.price-s.coins,rarity=i.rarity||(i.price?'rare':'starter');return `<article class="shopCollectible ${rarity} ${hot?'newUnlock':''}"><div class="shopCardTop"><span>${hot?'✨ UNLOCKED':rarity}</span><b>${equipped?'✓ Equipped':owned?'✓ Owned':i.price.toLocaleString()+' coins'}</b></div><button class="shopArt" data-preview="${i.id}" aria-label="Preview ${i.name}">${art(i)}</button><div class="shopCardCopy"><h3>${i.name}</h3><p>${i.description}</p><small>${owned?'Ready for your next adventure':!unlocked?lockText(E.unlockInfo(i.id)):need>0?'Save '+need.toLocaleString()+' more coins':'Ready to buy'}</small><div class="shopButtons"><button data-preview="${i.id}">${['subway-4','jetski-4'].includes(i.id)?'360° view':i.rarity==='legendary'&&i.slot==='skin'?'View artwork':'Preview'}</button><button data-buy="${i.id}" ${equipped||!unlocked||(!owned&&need>0)?'disabled':''}>${equipped?'Equipped':owned?'Equip':i.price.toLocaleString()+' · Buy & equip'}</button></div></div></article>`}
let extra='';if(cat==='all'||cat==='motorcycle'||cat==='dragon'){}else if(cat==='horse'){const slots=[...new Set(all.filter(i=>!['skin','ride'].includes(i.slot)).map(i=>i.slot))];extra=`<h3 class="shopSection">Choose your racer</h3><div class="shopCollection">${all.filter(i=>i.slot==='ride').map(card).join('')}</div><details class="shopCustomization" ${customOpen?'open':''}><summary>Make it your own: blankets, helmets & more</summary><label>Customize <select id="shopSlot">${slots.map(v=>`<option value="${v}" ${slot===v?'selected':''}>${({blanket:'Saddle blankets',helmet:'Helmets',mane:'Manes',tail:'Tails',wraps:'Leg wraps',trail:'Race trails',victory:'Victory moves',silk:'Racing colors'})[v]}</option>`).join('')}</select></label><div class="shopCollection">${all.filter(i=>i.slot===slot).map(card).join('')}</div></details>`}else extra=`<h3 class="shopSection">Finishing touches</h3><div class="shopCollection">${all.filter(i=>i.slot==='trim').map(card).join('')}</div>`;
$('items').className='restoredShop';$('items').innerHTML=`<section class="shopShowroom ${cat}"><div><span class="eyebrow">${titles[cat][0]}</span><h2>${chosen.name}</h2><p>${chosen.description}</p><b>${chosen.price?chosen.price.toLocaleString()+' coins · $'+chosen.price/100:'Included in your collection'}</b><small>Preview your favorites. Earn, collect, and equip for your next game.</small>${['subway-4','jetski-4'].includes(chosen.id)?`<figure class="moonReference">${plainArt(chosen)}<figcaption>Original ${chosen.name}</figcaption></figure>`:''}</div>${art(chosen,true)}</section><div class="shopSectionHead"><h3>${titles[cat][1]}</h3><span>${skins.filter(i=>s.owned.includes(i.id)).length} / ${skins.length} collected</span></div><div class="shopCollection">${(cat==='all'?all:skins).map(card).join('')}</div>${extra}`;
$('items').querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{selected=b.dataset.preview;render(cat,onCategory,changed,notify);$('items').querySelector('.shopShowroom').scrollIntoView({behavior:'smooth',block:'nearest'})});$('items').querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const it=E.catalog.find(i=>i.id===b.dataset.buy);const r=s.owned.includes(it.id)?E.equip(it.id):E.purchase(it.id);if(r.ok){selected=it.id;notify(it.name+' equipped!');changed()}else notify('Keep earning for this upgrade')});if($('shopSlot'))$('shopSlot').onchange=e=>{slot=e.target.value;render(cat,onCategory,changed,notify)};paint();window.ArcadeOrbit?.refresh()}
window.addEventListener('arcade-orbit-ready',()=>window.ArcadeOrbit.refresh());window.ArcadeShop={render};})();
